// تطبيع الأعمدة: يدعم أسماء عربية/إنجليزية شائعة
return $input.all().map((it) => {
  const r = it.json || {};
  const name = r.name ?? r.Name ?? r['product name'] ?? r['Product Name'] ?? r['اسم المنتج'] ?? r['الاسم'] ?? r.product ?? Object.values(r)[0];
  const serial = r.serial ?? r.Serial ?? r['serial number'] ?? r['Serial Number'] ?? r['سيريال'] ?? r['الرقم التسلسلي'] ?? Object.values(r)[1];
  return { json: { name: String(name ?? '').trim(), serial: String(serial ?? '').trim() } };
}).filter((i) => i.json.name);

// التقاط أول نتيجة من Apify والتطبيع لمخطط TEKDOM
const all = $input.all();
let p;
if (all.length === 1 && Array.isArray(all[0].json)) p = all[0].json[0];
else p = all[0] ? all[0].json : null;
p = p || {};

const meta = $('Build Search URL').first().json;

// الصور — أسماء حقول junglee الشائعة
const images = (p.highResolutionImages || p.images || p.galleryImages || p.imageUrls || (p.thumbnailImage ? [p.thumbnailImage] : []) || []).filter(Boolean).slice(0, 8);

// ── specs: كل المواصفات التقنية (products.specs) ──────────────────────────────
const specs = {};
// مصدر 1: attributes [{key,value}] — الأكثر شيوعاً في junglee
if (Array.isArray(p.attributes)) {
  for (const a of p.attributes) { if (a && a.key) specs[a.key] = String(a.value ?? ''); }
}
// مصدر 2: productOverview {key:value} — ملخص المنتج
if (p.productOverview && typeof p.productOverview === 'object') {
  for (const [k, v] of Object.entries(p.productOverview)) { if (!specs[k]) specs[k] = String(v ?? ''); }
}
// مصدر 3: technicalDetails
if (p.technicalDetails && typeof p.technicalDetails === 'object') {
  for (const [k, v] of Object.entries(p.technicalDetails)) { if (!specs[k]) specs[k] = String(v ?? ''); }
}

// ── variantAttributes: المميزات المحددة للـ variant (faceted search) ──────────
// خريطة المفاتيح الشائعة على أمازون (عربي + إنجليزي) → مفتاح موحّد
const VARIANT_KEY_MAP = {
  // اللون
  'Color': 'color', 'Colour': 'color', 'اللون': 'color', 'colour': 'color',
  // التخزين
  'Hard Disk Size': 'storage', 'Storage': 'storage', 'Flash Memory Size': 'storage',
  'الذاكرة': 'storage', 'سعة التخزين': 'storage', 'Memory Storage Capacity': 'storage',
  // الرام
  'RAM': 'ram', 'RAM Memory Installed Size': 'ram',
  'ذاكرة الوصول العشوائي': 'ram', 'حجم الذاكرة': 'ram',
  // الاتصال
  'Wireless communication technologies': 'connectivity', 'Connectivity': 'connectivity',
  'Cellular': 'connectivity', 'الاتصال': 'connectivity',
  // نظام التشغيل
  'Operating System': 'os', 'نظام التشغيل': 'os',
  // حجم الشاشة
  'Screen Size': 'screen_size', 'Display Size': 'screen_size', 'حجم الشاشة': 'screen_size',
  // السعة (للأجهزة المنزلية)
  'Capacity': 'capacity', 'السعة': 'capacity',
  // الموديل
  'Model Name': 'model', 'اسم الموديل': 'model',
};

const variantAttributes = {};

// استخرج من productOverview أولاً (أوضح وأبسط)
const overview = p.productOverview || {};
for (const [rawKey, normalKey] of Object.entries(VARIANT_KEY_MAP)) {
  if (overview[rawKey] !== undefined) {
    variantAttributes[normalKey] = String(overview[rawKey]).trim();
  }
}

// كمّل من attributes لو فيه حاجة ناقصة
if (Array.isArray(p.attributes)) {
  for (const a of p.attributes) {
    const normalKey = VARIANT_KEY_MAP[a.key];
    if (normalKey && !variantAttributes[normalKey]) {
      variantAttributes[normalKey] = String(a.value ?? '').trim();
    }
  }
}

// لون مباشر لو موجود كحقل منفصل (بعض نتائج junglee)
if (!variantAttributes.color && p.color) variantAttributes.color = String(p.color).trim();

const asin = (p.asin || p.ASIN || ('NOASIN-' + Date.now())).toString();
const baseName = (p.title || meta.name || 'product').toString();
const slug = (baseName.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 50) || 'product') + '-' + asin.toLowerCase();

const description = p.description || (Array.isArray(p.features) ? p.features.join('\n') : (p.features || null)) || null;

return [{ json: {
  name: p.title || meta.name,
  description,
  brand: p.brand || p.manufacturer || null,
  asin,
  slug,
  specs,
  variantAttributes,
  serial: meta.serial,
  images,
  ai_metadata: { source: 'amazon.eg', scraped_at: new Date().toISOString(), source_url: p.url || meta.searchUrl || null, asin }
} }];

// تجميع روابط الصور العامة + إعادة بيانات المنتج
const meta = $('Map Amazon Product').first().json;
const n = $('Split Images').all().length;
const base = 'https://xeylyyfmcucphggqwxdv.supabase.co/storage/v1/object/public/product-images';
const images = [];
for (let i = 0; i < n; i++) images.push(`${base}/${meta.asin}/${i}.jpg`);
return [{ json: { ...meta, images } }];
